-- ============================================================================
-- PGifts Direct clothing: finished per-POSITION sell price from Dave's sheet.
--
-- Seeds BOTH the "... off Total" columns (total_sell_price) AND the sheet
-- Garment column (garment_cost) so the read path can charge each print
-- position separately without double-counting the garment:
--     price = garment_cost + SUM over positions of (position Total - garment_cost)
-- Single position reduces to the Total column exactly. Garment is subtracted
-- using the SAME sheet the Total came from (white vs coloured), never mixed.
--
-- The old build summed garment+print (omitting profit) and had no white rows for
-- hoodie/sweat/polo (white showed dearer than coloured). Both fixed. No margin is
-- ever applied on top — profit is already in the sheet figures. Laltex untouched.
--
-- APPLY (CLAUDE.md §52): Supabase SQL Editor, paste, Run. No BEGIN/COMMIT.
-- Idempotent. Final SELECT must return 8 rows (4 garments x 2 variants).
-- ============================================================================

ALTER TABLE public.catalog_print_pricing ADD COLUMN IF NOT EXISTS total_sell_price numeric(10,2);
COMMENT ON COLUMN public.catalog_print_pricing.total_sell_price IS 'PGifts Direct clothing finished per-unit sell price (garment+print+profit) for a SINGLE print position, taken verbatim from Dave''s spreadsheet Total columns. Read with NO margin. Multi-position price = garment_cost + SUM(total_sell_price - garment_cost) per position. NULL -> legacy garment_cost+print path (e.g. hi-vis-vest).';
COMMENT ON COLUMN public.catalog_print_pricing.garment_cost IS 'For seeded Direct clothing rows: the spreadsheet Garment column (constant across colour counts within a band), subtracted from each position''s Total to get that position''s print+profit. For legacy rows: the original component garment cost.';

