-- Seeded: 180 UPDATEs + 108 INSERTs = 288 rows (expect 288).
SELECT cp.slug, x.colour_variant, COUNT(*) AS rows_with_total, MIN(x.garment_cost) AS min_garment, MAX(x.garment_cost) AS max_garment
FROM public.catalog_print_pricing x JOIN public.catalog_products cp ON cp.id = x.catalog_product_id
WHERE cp.slug IN ('t-shirts','hoodie','sweatshirts','polo') AND x.total_sell_price IS NOT NULL
GROUP BY cp.slug, x.colour_variant ORDER BY cp.slug, x.colour_variant;
